mapper.select:
SELECT * FROM (
	SELECT Tb.*, rownum rNum FROM (
		SELECT * FROM wishlist
		WHERE 1=1
		AND MemberId=#{memberId}
		ORDER BY no DESC
	) Tb
)
WHERE rNum >= #{start}
AND rNum <= #{end}

mapper.insert:
DECLARE
next_no NUMBER;
BEGIN
getnext_wishlist_no(next_no);
INSERT INTO wishlist (no, product_code, MemberId, created_date)
VALUES (next_no, #{product_code}, #{memberId}, CURRENT_TIMESTAMP);
END;
